/**
 * PathfindingGridHelper - 3D debug visualization for navigation grid cells.
 *
 * @extends THREE.Object3D
 */
export class PathfindingGridHelper {
    /**
     * Create a pathfinding grid helper.
     *
     * @param {PathfindingGrid} grid - The pathfinding grid to visualize.
     * @param {Object} [options={}] - Configuration options.
     * @param {number} [options.updateInterval=1000] - Update interval in ms.
     * @param {number} [options.walkableColor=0x00ff00] - Walkable cell color.
     * @param {number} [options.blockedColor=0xff0000] - Blocked cell color.
     * @param {number} [options.opacity=0.3] - Cell opacity.
     * @param {boolean} [options.showWalkable=true] - Show walkable cells.
     * @param {boolean} [options.showBlocked=false] - Show blocked cells.
     * @param {number} [options.yOffset=0.05] - Y offset above ground.
     */
    constructor(grid: PathfindingGrid, options?: {
        updateInterval?: number;
        walkableColor?: number;
        blockedColor?: number;
        opacity?: number;
        showWalkable?: boolean;
        showBlocked?: boolean;
        yOffset?: number;
    });
    /**
     * Reference to the pathfinding grid.
     * @type {PathfindingGrid}
     */
    grid: PathfindingGrid;
    /**
     * Update interval in milliseconds.
     * @type {number}
     */
    updateInterval: number;
    /**
     * Y offset for visualization elements.
     * @type {number}
     */
    yOffset: number;
    /**
     * Grid cell opacity.
     * @type {number}
     */
    opacity: number;
    _showWalkable: boolean;
    _showBlocked: boolean;
    _walkableColor: number;
    _blockedColor: number;
    _lastUpdate: number;
    _fetchPending: boolean;
    _walkableMesh: any;
    _blockedMesh: any;
    _walkableMaterial: any;
    _blockedMaterial: any;
    _cellGeometry: any;
    _matrix: any;
    _position: any;
    _scale: any;
    _quaternion: any;
    _initialized: boolean;
    _hasRendered: boolean;
    set showWalkable(value: boolean);
    /**
     * Whether to show walkable cells.
     * @type {boolean}
     */
    get showWalkable(): boolean;
    set showBlocked(value: boolean);
    /**
     * Whether to show blocked cells.
     * @type {boolean}
     */
    get showBlocked(): boolean;
    /**
     * Update debug visualization - call each frame or periodically.
     */
    update(): void;
    /**
     * Fetch grid data and render.
     *
     * @private
     */
    private _fetchAndRender;
    /**
     * Render navigation grid cells.
     *
     * @param {Object} gridData - Navigation grid data.
     * @private
     */
    private _renderGrid;
    /**
     * Render a set of cells as instanced mesh.
     *
     * @param {Array} cells - Array of cell data.
     * @param {number} cellSize - Size of each cell.
     * @param {string} meshKey - Property key for the mesh.
     * @param {THREE.Material} material - Material to use.
     * @private
     */
    private _renderCells;
    /**
     * Force refresh the grid visualization.
     */
    refresh(): void;
    /**
     * Dispose of the helper and release resources.
     */
    dispose(): void;
}
